uint64_t sqlfront(sqlite3*d){sqlite3_stmt*s;sqlok(sqlite3_prepare_v2(d,"SELECT frontier FROM meta WHERE id=1",-1,&s,nullptr));need(sqlite3_step(s)==SQLITE_ROW,"frontier row");uint64_t f=sqlite3_column_int64(s,0);need(sqlite3_step(s)==SQLITE_DONE,"one frontier row");sqlok(sqlite3_finalize(s));return f;}
struct Request{std::condition_variable cv;Op op{};bool done=false;Clock::time_point start;};
struct SqlBackend{sqlite3*d=nullptr;sqlite3_stmt*begin=nullptr,*end=nullptr,*update=nullptr,*front=nullptr;uint64_t last=0;
 SqlBackend(fs::path p,size_t n,int threshold){sqlok(sqlite3_open(p.c_str(),&d));exec(d,"PRAGMA journal_mode=WAL;PRAGMA synchronous=FULL;CREATE TABLE t(id INTEGER PRIMARY KEY,value INTEGER NOT NULL,text TEXT NOT NULL);CREATE TABLE meta(id INTEGER PRIMARY KEY,frontier INTEGER NOT NULL);INSERT INTO meta VALUES(1,0)");exec(d,("PRAGMA cache_size=-"+std::to_string(SQL_CACHE_KIB)).c_str());sqlite3_stmt*cachecheck;sqlok(sqlite3_prepare_v2(d,"PRAGMA cache_size",-1,&cachecheck,nullptr));need(sqlite3_step(cachecheck)==SQLITE_ROW&&sqlite3_column_int(cachecheck,0)==-SQL_CACHE_KIB,"actual SQLite cache budget");sqlok(sqlite3_finalize(cachecheck));exec(d,("PRAGMA wal_autocheckpoint="+std::to_string(threshold)).c_str());sqlite3_stmt*ins;sqlok(sqlite3_prepare_v2(d,"INSERT INTO t VALUES(?,?,?)",-1,&ins,nullptr));exec(d,"BEGIN");for(auto&x:fixture(n)){sqlok(sqlite3_bind_int64(ins,1,x.second.key));sqlok(sqlite3_bind_int64(ins,2,x.second.value));sqlok(sqlite3_bind_text(ins,3,x.second.text,-1,SQLITE_TRANSIENT));need(sqlite3_step(ins)==SQLITE_DONE,"fixture insert");sqlok(sqlite3_reset(ins));}sqlok(sqlite3_finalize(ins));exec(d,"COMMIT;PRAGMA wal_checkpoint(TRUNCATE)");sqlok(sqlite3_prepare_v2(d,"BEGIN IMMEDIATE",-1,&begin,nullptr));sqlok(sqlite3_prepare_v2(d,"COMMIT",-1,&end,nullptr));sqlok(sqlite3_prepare_v2(d,"UPDATE t SET value=value+? WHERE id=?",-1,&update,nullptr));sqlok(sqlite3_prepare_v2(d,"UPDATE meta SET frontier=? WHERE id=1 AND frontier=?",-1,&front,nullptr));}
 void commit(const std::vector<Op>&ops){need(sqlite3_step(begin)==SQLITE_DONE,"begin");sqlok(sqlite3_reset(begin));uint64_t next=last;for(auto&o:ops){need(o.id==++next,"SQL request sequence");sqlok(sqlite3_bind_int64(update,1,o.delta));sqlok(sqlite3_bind_int64(update,2,o.key));need(sqlite3_step(update)==SQLITE_DONE&&sqlite3_changes(d)==1,"SQL actual request");sqlok(sqlite3_reset(update));}sqlok(sqlite3_bind_int64(front,1,next));sqlok(sqlite3_bind_int64(front,2,last));need(sqlite3_step(front)==SQLITE_DONE&&sqlite3_changes(d)==1,"atomic SQL frontier");sqlok(sqlite3_reset(front));need(sqlite3_step(end)==SQLITE_DONE,"SQL commit");sqlok(sqlite3_reset(end));last=next;}
 ~SqlBackend(){if(begin)sqlite3_finalize(begin);if(end)sqlite3_finalize(end);if(update)sqlite3_finalize(update);if(front)sqlite3_finalize(front);if(d)sqlite3_close(d);}
};
void trial(fs::path p,size_t clients,size_t count,int candidate,int pair,int campaign,FILE*out){constexpr size_t n=100000;auto setup_start=Clock::now();need(count%clients==0,"equal client loads");const char*names[]={"native","sqlite_64","sqlite_128","sqlite_256","sqlite_512","sqlite_1024","sqlite_serial_128"};std::unique_ptr<Engine>native;std::unique_ptr<SqlBackend>sql;if(candidate==0)native=std::make_unique<Engine>(p,n,true);else sql=std::make_unique<SqlBackend>(p,n,candidate==6?128:std::stoi(std::string(names[candidate]).substr(7)));size_t maxgroup=candidate==6?1:MAX_GROUP;double backend_setup=elapsed(setup_start);
 std::mutex mutex;std::condition_variable ready,changed;std::deque<Request*>queue;bool start=false;size_t waiting=0,issued=0,processed=0,transactions=0;std::exception_ptr error;std::vector<double>lat(count);std::vector<bool>acked(count,false);std::vector<std::shared_ptr<Request>>active(clients);std::array<size_t,MAX_GROUP+1>hist{};
 double commits=0;if(DIRECT_OWNER){need(clients==1&&MAX_GROUP==1,"direct owner is singleton");io={};dsync_write_calls=0;auto begin=Clock::now();for(size_t k=0;k<count;k++){auto request_start=Clock::now();auto ops=changes(issued++,1,n);if(native)native->commit(ops);else sql->commit(ops);need(ops.size()==1&&ops[0].id==k+1&&!acked[k],"direct unique ordered ack");acked[k]=true;lat[k]=elapsed(request_start);hist[1]++;transactions++;processed++;}commits=elapsed(begin);}else{
 std::thread writer([&]{try{while(processed<count){std::vector<Request*>g;{std::unique_lock<std::mutex>lock(mutex);changed.wait(lock,[&]{return !queue.empty()||error;});if(error)return;while(!queue.empty()&&g.size()<maxgroup){g.push_back(queue.front());queue.pop_front();}}std::vector<Op>ops;for(auto*r:g)ops.push_back(r->op);if(native)native->commit(ops);else sql->commit(ops);{std::lock_guard<std::mutex>lock(mutex);hist[g.size()]++;transactions++;processed+=g.size();for(auto*r:g){r->done=true;if(TARGETED)r->cv.notify_one();}}if(!TARGETED)changed.notify_all();}}catch(...){std::lock_guard<std::mutex>lock(mutex);error=std::current_exception();changed.notify_all();ready.notify_all();for(auto&a:active)if(a)a->cv.notify_all();}});
 std::vector<std::thread>threads;for(size_t c=0;c<clients;c++)threads.emplace_back([&,c]{try{{std::unique_lock<std::mutex>lock(mutex);waiting++;ready.notify_all();ready.wait(lock,[&]{return start||error;});if(error)return;}for(size_t k=0;k<count/clients;k++){auto holder=std::make_shared<Request>();Request&r=*holder;r.start=Clock::now();std::unique_lock<std::mutex>lock(mutex);r.op=changes(issued++,1,n).at(0);active[c]=holder;queue.push_back(&r);if(TARGETED){changed.notify_one();r.cv.wait(lock,[&]{return r.done||error;});}else{changed.notify_all();changed.wait(lock,[&]{return r.done||error;});}if(error)return;need(!acked[r.op.id-1],"duplicate ack");acked[r.op.id-1]=true;lat[r.op.id-1]=elapsed(r.start);active[c].reset();}}catch(...){std::lock_guard<std::mutex>lock(mutex);error=std::current_exception();changed.notify_all();ready.notify_all();for(auto&a:active)if(a)a->cv.notify_all();}});
 Clock::time_point begin;{std::unique_lock<std::mutex>lock(mutex);ready.wait(lock,[&]{return waiting==clients||error;});io={};dsync_write_calls=0;begin=Clock::now();start=true;ready.notify_all();}for(auto&t:threads)t.join();writer.join();commits=elapsed(begin);}
 if(error)std::rethrow_exception(error);need(issued==count&&processed==count&&std::all_of(acked.begin(),acked.end(),[](bool x){return x;}),"complete unique acks");size_t summed=0,groups=0;for(size_t i=1;i<hist.size();i++){summed+=i*hist[i];groups+=hist[i];}need(summed==count&&groups==transactions,"group histogram");auto s=Clock::now();if(native)native->checkpoint();else exec(sql->d,"PRAGMA wal_checkpoint(TRUNCATE)");double final=elapsed(s);double through_final=elapsed(setup_start);Metrics phase{};if(native)phase=native->met;IOStats measured=io;auto measured_dsync=dsync_write_calls;int cache_used=0,cache_high=0;if(sql)sqlok(sqlite3_db_status(sql->d,SQLITE_DBSTATUS_CACHE_USED,&cache_used,&cache_high,0));auto want=expected(n,1,count);if(native)need(native->rows==want&&native->frontier==count,"native rows/frontier final");else need(sqlrows(sql->d)==want&&sqlfront(sql->d)==count,"SQL rows/frontier final");native.reset();sql.reset();s=Clock::now();if(candidate==0){Engine e(p,n,true);need(e.rows==want&&e.frontier==count,"native rows/frontier reopen");}else{sqlite3*d;sqlok(sqlite3_open(p.c_str(),&d));need(sqlrows(d)==want&&sqlfront(d)==count,"SQL rows/frontier reopen");sqlok(sqlite3_close(d));}double recovery=elapsed(s);need(measured.errors==0&&measured.sync_calls>=transactions&&measured.write_calls>0,"IO counter validity");fprintf(out,"{\"queue\":\"%s\",",DIRECT_OWNER?"direct-owner":TARGETED?"targeted":"broadcast");fprintf(out,"\"campaign\":%d,\"clients\":%zu,\"requests\":%zu,\"pair\":%d,\"candidate\":\"%s\",\"transactions\":%zu,\"commit_s\":%.9f,\"final_s\":%.9f,\"recovery_s\":%.9f,\"p95_s\":%.9f,\"p99_s\":%.9f,\"sync_calls\":%llu,\"sync_s\":%.9f,\"write_bytes\":%llu,\"frontier\":%zu,\"frame_bytes\":%zu,\"hist\":[",campaign,clients,count,pair,names[candidate],transactions,commits,final,recovery,percentile(lat,.95),percentile(lat,.99),(unsigned long long)measured.sync_calls,measured.sync_s,(unsigned long long)measured.bytes,count,SLOT);for(size_t i=0;i<hist.size();i++)fprintf(out,"%s%zu",i?",":"",hist[i]);fprintf(out,"],\"dense\":%d,\"checkpoint_s\":%.9f,\"lookup_s\":%.9f,\"encode_s\":%.9f,\"publish_s\":%.9f,\"native_write_s\":%.9f,\"value_banks\":%d,\"sql_cache_kib\":%d,\"sqlite_cache_used_bytes\":%d,\"dsync_packed\":%d,\"dsync_write_calls\":%llu,\"direct_owner\":%d,\"ring_capacity\":%zu,\"region_count\":%zu,\"checkpoint_bytes\":%llu,\"checkpoint_regions\":%llu,\"checkpoint_count\":%llu,\"commit_sync_s\":%.9f",DENSE,phase.checkpoint,phase.lookup,phase.encode,phase.publish,phase.write,VALUE_BANKS,SQL_CACHE_KIB,cache_used,DSYNC_PACKED,(unsigned long long)measured_dsync,DIRECT_OWNER,size_t(CAP),size_t(REG),(unsigned long long)phase.cpbytes,(unsigned long long)phase.regions,(unsigned long long)phase.cps,phase.sync);fprintf(out,",\"prefill\":%d,\"backend_setup_s\":%.9f,\"through_final_wall_s\":%.9f,\"valid\":true}\n",PREFILL,backend_setup,through_final);fflush(out);}
int main(int argc,char**argv){try{need(argc>=5&&argc<=7,"NEW_ROOT CLIENTS REQUESTS CAMPAIGN [PAIR [CANDIDATE]]");fs::path root=argv[1];size_t clients=std::stoull(argv[2]),count=std::stoull(argv[3]);int campaign=std::stoi(argv[4]);need(fs::create_directory(root),"fresh root");FILE*out=fopen((root/"raw.jsonl").c_str(),"wx");need(out,"output");int first=argc>=6?std::stoi(argv[5]):0,last=argc>=6?first+1:3;need(first>=0&&first<3,"pair bound");int requested=argc==7?std::stoi(argv[6]):-1;need((argc==7?requested>=0:requested==-1)&&requested<7,"candidate bound");for(int pair=first;pair<last;pair++)for(int phase=0;phase<(argc==7?1:7);phase++){int c=argc==7?requested:(pair+phase)%7;trial(root/(std::to_string(pair)+"-"+std::to_string(c)),clients,count,c,pair,campaign,out);}fclose(out);std::cout<<"PASS"<<(last-first)*(argc==7?1:7)<<"records clients="<<clients<<" requests="<<count<<" stored/recovered request frontier verified\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
